from torch.utils.cpp_extension import load_inline

# CUDA kernel implementing argmax over an arbitrary dimension for fp16 tensors
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void argmax_kernel(const __half* __restrict__ input,
                              int64_t* __restrict__ output,
                              int outer,
                              int reduction,
                              int inner) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = outer * inner;
    if (idx >= total) return;

    int o = idx / inner;          // index in outer dimension
    int i = idx % inner;          // index in inner dimension

    // offset of the first element (r = 0) for this (o,i) pair
    int base = (o * reduction) * inner + i;

    float best_val = __half2float(input[base]);
    int   best_idx = 0;

    #pragma unroll
    for (int r = 1; r < reduction; ++r) {
        int offset = base + r * inner;
        float val = __half2float(input[offset]);
        if (val > best_val) {
            best_val = val;
            best_idx = r;
        }
    }
    output[idx] = best_idx;
}
'''

# Compile the kernel as a PyTorch extension
argmax_mod = load_inline(name='argmax_cuda',
                         cpp_sources='',
                         cuda_sources=cuda_source,
                         functions=['argmax_kernel'],
                         verbose=False)

def _argmax_fp16_cuda(x: torch.Tensor, dim: int) -> torch.Tensor:
    """
    CUDA implementation of torch.argmax for fp16 tensors.
    Returns a LongTensor with the reduced dimension removed.
    """
    assert x.is_cuda and x.dtype == torch.float16, "Input must be CUDA fp16 tensor"
    ndim = x.dim()
    dim = dim % ndim  # handle negative dims

    # Compute outer, reduction, inner sizes
    outer = 1
    for d in range(dim):
        outer *= x.shape[d]

    reduction = x.shape[dim]

    inner = 1
    for d in range(dim + 1, ndim):
        inner *= x.shape[d]

    total = outer * inner
    out = torch.empty(total, dtype=torch.long, device='cuda')

    threads = 256
    blocks = (total + threads - 1) // threads

    stream = torch.cuda.current_stream()
    argmax_mod.argmax_kernel(grid=(blocks,),
                             block=(threads,),
                             args=(x.contiguous(), out, outer, reduction, inner),
                             stream=stream)

    out_shape = list(x.shape)
    del out_shape[dim]
    return out.view(out_shape)

